INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Änderungen ohne Testprotokolle nachvollziehbar?', 2, '[{"text": "Nein", "correct": true, "because": "Tests zeigen Ergebnisse"}, {"text": "Ja", "correct": false, "because": "Fehlende Validierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Testprotokollen?', 3, '[{"text": "Nachverfolgbarkeit", "correct": true, "because": "Dokumentiert Ergebnisse"}, {"text": "Performance", "correct": false, "because": "Kein direkter Fokus"}, {"text": "Design", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Testprotokoll?', 5, '[{"text": "Testfälle", "correct": true, "because": "Definiert Szenarien"}, {"text": "Ergebnisse", "correct": true, "because": "Zeigt Erfolg"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}, {"text": "Hardware-Specs", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Änderungen brauchen Datum. b) Testprotokolle sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) essenziell für Audits"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Testprotokollen?', 4, '[{"text": "Testergebnisse", "correct": false, "because": "Kern der Dokumentation"}, {"text": "Änderungsgrund", "correct": false, "because": "Gibt Kontext"}, {"text": "Schriftart", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Testprotokolle immer manuell erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Automatisierung möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System nutze ich für Änderungsprotokolle?', 3, '[{"text": "Git", "correct": true, "because": "Nachverfolgt Änderungen"}, {"text": "E-Mail", "correct": false, "because": "Unstrukturiert"}, {"text": "Notepad", "correct": false, "because": "Keine Versionierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Testprotokolle effektiv?', 5, '[{"text": "Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Vollständigkeit", "correct": true, "because": "Alle Tests abdecken"}, {"text": "Hohe Auflösung", "correct": false, "because": "Irrelevant"}, {"text": "Lange Texte", "correct": false, "because": "Ermüdend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Testprotokolle sind nur für Audits. b) Änderungen brauchen keine Tests. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Tests für Qualität, nicht nur Audits"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) unvollständig"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Änderungsprotokolle?', 4, '[{"text": "Datum", "correct": false, "because": "Zeitpunkt wichtig"}, {"text": "Beschreibung", "correct": false, "because": "Erklärt Änderung"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Testprotokolle nur für Entwickler?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für QA und Audits"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen gehören in ein Testprotokoll?', 4, '[{"text": "Testbedingungen", "correct": true, "because": "Definiert Rahmen"}, {"text": "Ergebnisse", "correct": true, "because": "Zeigt Status"}, {"text": "UI-Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Änderungen ohne Protokoll okay sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nachverfolgung nötig"}, {"text": "Ja", "correct": false, "because": "Risiko für Audits"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Testprotokollen?', 3, '[{"text": "Genauigkeit", "correct": true, "because": "Sichert Validität"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Länge", "correct": false, "because": "Kürze besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Testprotokolle brauchen Ergebnisse. b) Änderungen sind immer getestet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein gutes Änderungsprotokoll?', 5, '[{"text": "Transparenz", "correct": true, "because": "Zeigt Verlauf"}, {"text": "Auditfähigkeit", "correct": true, "because": "Nachweisbar"}, {"text": "Hohe Leistung", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnelle Tests", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Testprotokollen unwichtig?', 3, '[{"text": "Testfälle", "correct": false, "because": "Kern der Dokumentation"}, {"text": "Datum", "correct": false, "because": "Zeitpunkt relevant"}, {"text": "Monitorgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen Testprotokolle die Versionskontrolle?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzen sich"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Änderungen immer dokumentiert werden müssen?', 2, '[{"text": "Ja", "correct": true, "because": "Für Audits nötig"}, {"text": "Nein", "correct": false, "because": "Risiko bei Unterlassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für Testprotokolle entscheidend?', 4, '[{"text": "Reproduzierbarkeit", "correct": true, "because": "Ermöglicht Nachprüfung"}, {"text": "Hohe Komplexität", "correct": false, "because": "Verwirrt"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung besser"}]');
